WITH filtered AS (SELECT *, CASE WHEN country IN ('DE', 'US') THEN 'Tier 1' ELSE 'Other' END AS country_group, CONCAT(city, ' ', segment) AS city_segment, COALESCE(segment, 'DIRECT') AS resolved_segment FROM customers WHERE signup_date >= DATE '2024-03-25' AND city IS NOT NULL AND name LIKE 'No%') SELECT s.* FROM filtered s WHERE NOT EXISTS (SELECT 1 FROM subscriptions c WHERE c.customer_id = s.id AND c.customer_id IS NOT NULL);
